def rule(i, title, summary, sources, planets, commodities, timeframe='अनिर्दिष्ट', signal='अन्य', status='reference', reason=None, conditions=None):
    if status not in {'computable','reference','missing'}:
        if reason is None:
            reason, status = status, 'reference'
    if reason is None:
        reason = 'यह संक्रान्ति/चन्द्र-दर्शन आधारित वर्णनात्मक नियम है; दिए हुए DSL में इसका पूरा ट्रिगर और समय-संदर्भ व्यक्त नहीं किया जा सकता।'
    return {
        'id': f'R03-{i:03d}', 'title': title, 'summary': summary,
        'source_ids': sources, 'planets': planets, 'commodities': commodities,
        'timeframe': timeframe, 'signal': signal, 'status': status,
        'reason': reason, 'conditions': [] if conditions is None else conditions
    }

