add('अमावास्या/पूर्णिमा संक्रान्ति-संग्रह','मेष में गेहूँ-जौ-चना चौथे मास लाभ; वृषभ स्रोत-वाक्य बीच में कटकर B00729 में उद्भिज पदार्थ चौथे मास तक जाता है; मिथुन में बादल हों तो गुड़-खाँड-नमक छठे मास; कर्क में धातु-सरसों-तेल-तिल-घृत-गुड़-खाँड दूसरे मास; सिंह में पुच्छलतारा हो तो लाख-चमड़ा-मोती-मूंगा-हीरा पाँचवें मास।',['B00725','B00726','B00729'],['सूर्य','चंद्रमा'],['गेहूँ','जौ','चना','उद्भिज पदार्थ','गुड़','खाँड','नमक','सोना','चाँदी','लोहा','पीतल','सरसों','तेल','तिल','घृत','लाख','चमड़ा','मोती','मूंगा','हीरा'],'मासिक','तेजी','अमावास्या/पूर्णिमा, मौसम और पुच्छलतारा जैसे ट्रिगर तथा भविष्य-लाभ DSL में पूरे नहीं हैं; B00726 का मध्यांश भी अनुपलब्ध है।')
add('कन्या से मीन अमावास्या/पूर्णिमा-संग्रह','कन्या में ग्रहण के साथ वाहन-पशु छठे मास लाभ; तुला में बादल/वर्षा पर ज्वार-बाजरा-मक्का-दालें-कस्तूरी-केसर-हल्दी-घृत छठे मास; वृश्चिक में ग्रहण पर धातु मंदी में खरीदकर उसी मास तेजी पर बिक्री; धनु में बादल पर मोती-मूंगा-हीरा-केसर-कस्तूरी-कपूर छठे मास; मकर/कुम्भ में पुच्छलतारा पर अनाज/लोहे के बर्तन दूसरे मास; मीन में बादल पर जवाहिरात-धातु-आलू-अरबी-कोयला-पत्थर-लकड़ी छठे मास।',['B00729','B00730','B00731','B00734'],['सूर्य','चंद्रमा'],['वाहन-पशु','ज्वार','बाजरा','मक्का','उड़द','मूँग','मोंठ','कस्तूरी','केसर','हल्दी','घृत','सोना','चाँदी','लोहा','ताँबा','पीतल','मोती','मूंगा','हीरा','कपूर','गेहूँ','जौ','चना','लोहे के बर्तन','आलू','अरबी','कोयला','पत्थर','लकड़ी'],'मासिक','तेजी','ग्रहण/बादल/वर्षा/पुच्छलतारा और future lag/खरीद-बिक्री जैसे बहु-शर्तीय संदर्भ DSL में व्यक्त नहीं हैं।')

add('वारगत चन्द्र-दर्शन','रवि पर सोना-चाँदी तेज, रुई घट-बढ़; सोम पर सोना-रुई-सूत-वस्त्र-रंग-अनाज तेज; मंगल पर सोना-चाँदी घट-बढ़ के बाद तेज, अन्न तेज और रुई पहले मंद फिर तेज।',['B00735','B00736'],['चंद्रमा'],['सोना','चाँदी','रुई','सूत','वस्त्र','रंग','अनाज'],'दैनिक','मिश्रित')
add('बुध से शनिवार चन्द्र-दर्शन','बुध पर घृत-अन्न तेज और रुई-चाँदी-सोना-सूत-सन-वस्त्र-गुड़-खाँड-शक्कर मंद; गुरु पर रुई-कपास-सूत-वस्त्र-घृत-तेल-सरसों तेज और सोना-चाँदी-गुड़-खाँड मंद; शुक्र पर चावल-चना-उड़द-अन्न-सरसों-तिल-तेल-ऊनी वस्त्र मंद, सोना-चाँदी-रुई पहले घट-बढ़ फिर तेज; शनि पर चाँदी-सोना-रुई-सरसों-सूत-वस्त्र भारी तेज।',['B00739'],['चंद्रमा'],['घृत','अन्न','रुई','चाँदी','सोना','सूत','सन','वस्त्र','गुड़','खाँड','शक्कर','कपास','तेल','सरसों','चावल','चना','उड़द','तिल','ऊनी वस्त्र'],'दैनिक','मिश्रित')
